-- strata native SQL dump v1

-- schema
CREATE TABLE engineering_record (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL,
    number INTEGER NOT NULL,
    title TEXT NOT NULL,
    status TEXT NOT NULL,
    document TEXT NOT NULL CHECK(json_valid(document)),
    revision INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL, slug TEXT NOT NULL DEFAULT '',
    UNIQUE(kind, number)
);

CREATE TABLE record_relation (
    source_id TEXT NOT NULL REFERENCES engineering_record(id),
    relation TEXT NOT NULL,
    target_id TEXT NOT NULL REFERENCES engineering_record(id),
    PRIMARY KEY(source_id, relation, target_id)
);

CREATE TABLE record_revision (
    record_id TEXT NOT NULL REFERENCES engineering_record(id),
    revision INTEGER NOT NULL,
    document TEXT NOT NULL CHECK(json_valid(document)),
    changed_at TEXT NOT NULL,
    changed_by TEXT,
    change_summary TEXT,
    PRIMARY KEY(record_id, revision)
);

CREATE TABLE evidence (
    id TEXT PRIMARY KEY,
    record_id TEXT NOT NULL REFERENCES engineering_record(id),
    kind TEXT NOT NULL,
    title TEXT NOT NULL,
    uri TEXT,
    content TEXT,
    metadata TEXT CHECK(metadata IS NULL OR json_valid(metadata))
);

CREATE TABLE code_reference (
    record_id TEXT NOT NULL REFERENCES engineering_record(id),
    relation TEXT NOT NULL,
    path TEXT NOT NULL,
    symbol TEXT,
    line_start INTEGER,
    line_end INTEGER
);


-- data
INSERT INTO engineering_record (id, kind, number, title, status, document, revision, created_at, updated_at, slug) VALUES ('EDR-0001', 'EDR', 1, 'Phase 1 rustdoc enrichment implementation', 'draft', '{"alternatives":"Retain a shared target directory, which Cargo serializes with its build lock; retain serial enrichment; keep raw serde_json navigation; or guard rather than remove rustdoc visibility writes. The experiment showed per-crate target directories are required for actual overlap, and the visibility sample showed rustdoc overwrote private with crate.","consequences":"The representative three-crate workspace improved from 3.01s before to 1.67s after. Compiled dependency artifacts are less reusable across crates because target directories are isolated. Qualified names, signatures, trait implementations, and IMPL_TRAIT edges are computed without database access and committed serially. Format-version mismatches remain loud; other crate failures warn and skip.","context":"Implementing PDR-0002 Phase 1 in src/rustdoc_enricher.rs after the required target-locking, timing, rustdoc-types, and visibility experiments.","decision":"Hoist one SQLite node-map snapshot into Arc, compute typed rustdoc enrichment per crate in rayon workers using per-crate Cargo target directories, then apply all successful results serially in one transaction. Adopt rustdoc-types 0.57.4 for format_version 57 and stop writing visibility from rustdoc so tree-sitter remains authoritative.","evidence":"Shared-target concurrent rustdoc: alpha 0.67s and beta 1.15s, with beta blocking on Cargo build-directory lock. Baseline graphlite discover/enrich on the same workspace: 3.01s. Changed implementation: 1.67s with three concurrent rustdoc jobs. Visibility sample after change: private_item=private, public_item=pub, crate_item=pub(crate), restricted_item=pub(in crate::inner). rustdoc-types 0.57.x declares FORMAT_VERSION 57."}', 1, '2026-08-21T16:59:52.168854833+00:00', '2026-08-21T16:59:52.168854833+00:00', 'phase-1-rustdoc-enrichment-implementation');
INSERT INTO engineering_record (id, kind, number, title, status, document, revision, created_at, updated_at, slug) VALUES ('PDR-0001', 'PDR', 1, 'GraphLite pipeline and query design', 'approved', '{"alternatives":"A single unified language-server-protocol backend (rust-analyzer, tsserver, etc.) instead of tree-sitter+rustdoc: rejected as the primary mechanism because LSP servers require a working build and per-language server management; tree-sitter''s syntax-only parsing tolerates broken/mid-edit code and covers six languages uniformly. An LSP client (lsp_client.rs) exists in this codebase for one specific feature (semantic rename) rather than as the core indexing mechanism -- README.md now states rename is deprecated in favor of editor-native LSP rename, though the CLI (`graphlite rename --help`, main.rs Commands::Rename) still dispatches it; this inconsistency is unresolved as of this record.","components":"tree-sitter parser + per-language .scm query files (queries/*.scm) for symbol/call extraction; rustdoc_enricher.rs (cargo invocation, JSON parsing, node reconciliation); resolver.rs (use-statement resolution to CALLS_RESOLVED edges); roles.rs (topology-based role classification); query.rs (all read-path commands and XML rendering); schema.rs (SQLite schema, incremental hashing); watch.rs (filesystem watch + re-index); annotate.rs (persistent human/LLM notes on symbols, with staleness tracking against re-indexed content); policy.rs + violations.rs (architecture layer/context coupling rules, built-in packs, custom overrides).","constraints":"Must work without requiring the target project''s build to succeed (tree-sitter parses syntax, not semantics, so it tolerates broken code). Semantic enrichment for Rust is necessarily best-effort on top of that, since it depends on a working compiler toolchain. Output must carry its own token cost so an agent can budget context spend without guessing.","data_model":"SQLite tables include nodes (symbol id, stable_id, kind, file, range, visibility, role, fan_in/fan_out), edges (from/to node id, edge_type, source, confidence_tier), annotations (intent, behavior, tags, source, confidence, staleness), node_diagnostics (clippy findings), and crate-risk tables (cargo-audit ingestion). stable_id (e.g. \"src/policy.rs::fn::effective_policy\") is the durable cross-query identifier; numeric node ids are session-local.","evidence":"Verified directly, in a real session working against both this codebase and a second real Rust workspace (github.com Strata project, 4 crates / 211 symbols): `graphlite deps` correctly derived crate dependency direction with zero manual configuration; `graphlite context`/`blast-radius`/`trace-path` reproduced call-structure facts (e.g. cli/src/publish.rs::fn::run -> stage::publish -> stage::replace_target in 2 hops) that would otherwise require reading multiple full files; policy layering (kernel/records=domain, store=infra, strata=adapter) matched the target project''s own documented architecture with zero manual dependency-direction violations found.","experiments":"None formally recorded prior to this backfill. The verification described under `evidence` was exploratory, ad hoc, and not captured as a repeatable experiment at the time it was run.","failure_modes":"Missing grammar or unparseable file: skipped with a logged warning, not a hard failure. Rustdoc enrichment failing for one crate (nightly not installed, cargo error) is caught per-crate in enrich_crates and logged as a warning, not propagated -- the rest of the index still completes. A rustdoc JSON format_version mismatch against EXPECTED_FORMAT_VERSION is a hard, loud failure (bail!) rather than a silent partial parse. Invalid FTS5 query syntax passed to `symbols` currently surfaces as a raw anyhow backtrace rather than a clean error -- an observed gap, not yet fixed.","interfaces":"A single `graphlite` CLI binary (clap-derived subcommands), documented in README.md and in skills/graphlite.md (a Claude Code skill file distributed inside this repo, describing the recommended query-escalation workflow and per-command token budgets). `.graphlite/config.toml` (TOML) configures ignore patterns, workspace crate-to-layer mapping, and policy overrides. No network interface; output is XML (or Markdown via --md) to stdout.","open_questions":"Should rustdoc-based enrichment continue to exist as a separate mechanism from the LSP client already present in this codebase, or should one subsume the other -- and does that decision depend on resolving the rename-deprecation inconsistency noted under `alternatives` first? Tracked forward in RFC-0002.","problem":"An LLM agent working in a codebase needs to answer structural questions (who calls this, what would change if I edit that, what''s the architecture) without either reading whole files defensively (expensive, imprecise, doesn''t scale with codebase size) or lacking any structural ground truth at all (hallucinated call graphs, missed call sites).","proposed_design":"A three-stage pipeline writes into one SQLite database (.graphlite/codegraph.db): (1) tree-sitter parses all supported languages in parallel (rayon) into symbols and syntactic CALLS edges, confidence=0.8; (2) for Rust, `cargo +nightly rustdoc --output-format json` is run per affected crate and the resulting JSON is parsed to attach qualified_name, visibility, and IMPL_TRAIT edges, source=\"rustdoc\"; (3) a use-statement resolver produces CALLS_RESOLVED edges with a high/medium/low confidence tier, source=\"resolver\". A separate role-inference pass classifies each symbol (entrypoint, orchestrator, infra, domain, utility, leaf, model) from graph topology (fan-in/fan-out shape), independent of any per-language logic. Every query command renders XML via a shared writer and reports its own token count in the output header.","requirements":"Index Rust, TypeScript, JavaScript, Svelte, HTML, and CSS source into symbols and call edges. Provide token-metered query commands (map, symbols, graph, context, blast-radius, trace-path) that return XML with an explicit token/line budget the caller controls. Re-indexing must be incremental, keyed on file content hash, so repeated queries against a large codebase stay cheap. For Rust specifically, enrich beyond syntactic tree-sitter facts with real semantic data: qualified names, visibility, trait implementations.","resulting_decisions":"This record captures already-implemented, working design as of the session that backfilled it; it does not itself constitute a new decision. RFC-0002 (rustdoc/cargo enrichment redesign) is the forward-looking record that references this PDR as the description of the system it proposes to change.","risks":"rustdoc enrichment requires the nightly toolchain and consumes unstable, only-loosely-versioned JSON output (mitigated by the format_version assertion, but every nightly rustdoc-json schema change still requires a manual constant bump and re-verification of every raw serde_json::Value access path, since rustdoc-types is not used). rustdoc enrichment runs strictly serially per crate (enrich_crates is a plain for loop) despite rayon already being a dependency used elsewhere in this same pipeline (discover.rs) -- on a multi-crate workspace this is very likely the dominant cost of a full re-index, and is the concrete, felt performance problem motivating RFC-0002. query.rs has grown to 2945 lines mixing orchestration and XML rendering for every command, a maintainability risk independent of correctness."}', 3, '2026-08-21T15:46:21.875482677+00:00', '2026-08-21T15:46:32.846054632+00:00', 'graphlite-pipeline-and-query-design');
INSERT INTO engineering_record (id, kind, number, title, status, document, revision, created_at, updated_at, slug) VALUES ('PDR-0002', 'PDR', 2, 'Rust enrichment redesign: parallel rustdoc, typed parsing, phased LSP evaluation', 'approved', '{"alternatives":"Do nothing / accept serial enrich_crates -- rejected, this is the maintainer''s own directly-felt problem (RFC-0002''s motivation). Ship only Phase 1''s parallelization (a) without typed parsing (b) -- leaves the schema-drift maintenance risk unaddressed for no real benefit, since (a) and (b) touch the same function and are cheaper to do together than sequentially. Commit to Phase 2 (LSP sourcing) in the same implementation pass as Phase 1 -- rejected by this PDR specifically: the spike (RFC-0002-EV-001) found a real, unresolved reliability gap (the quiescent readiness signal never fired in a 170s wait) that makes Phase 2 a correctness risk, not just a speed opportunity, if rushed into the same pass as two independently low-risk changes. Phasing it separately lets Phase 1 ship without waiting on Phase 2''s resolution, and keeps \"efficient\" from being pursued at the expense of \"correct.\"","components":"src/rustdoc_enricher.rs (restructured per Phase 1: build_node_map hoisted, run_and_apply split into pure-compute + serial-apply stages, serde_json::Value replaced with rustdoc_types::Crate). Cargo.toml (+rustdoc-types dependency, version verified against this project''s pinned nightly''s format_version before adoption). src/parser.rs (extract_visibility, line 184 -- referenced, not modified, as the pre-existing source of truth Phase 1 step 5 defers to). src/lsp_client.rs (untouched by Phase 1; Phase 2, if pursued, needs a request-pipelining redesign that is explicitly out of this PDR''s scope).","constraints":"rusqlite::Connection is !Send -- a parallel enrichment stage cannot hold or share a Connection across worker threads; any parallel stage must be pure computation only, with all DB writes serialized afterward. Cargo''s own target-directory locking behavior when multiple `cargo +nightly rustdoc` invocations run concurrently against one shared --target-dir is unverified in this session (RFC-0002''s own open question 2, still unresolved) -- Phase 1 implementation must not assume parallel invocations actually run concurrently against a shared target dir without first measuring it. LSP-based sourcing (Phase 2) is constrained by the unresolved quiescent-signal reliability gap surfaced in RFC-0002-EV-001 and must not ship until that gap is understood. Nightly toolchain dependency and rustdoc JSON format-version fragility are pre-existing and out of this PDR''s scope to remove.","data_model":"No schema changes. nodes.qualified_name / nodes.visibility / nodes.trait_impl columns and IMPL_TRAIT edges keep their existing meaning and are populated by the same source=\"rustdoc\" provenance in Phase 1; only the code path producing them changes internally.","evidence":"RFC-0002-EV-001 (this repo''s own feasibility spike, 2026-08-21, evidence attached to RFC-0002) -- hover/documentSymbol fidelity comparison against cached rustdoc JSON, and the visibility-overwrite finding. Confirmed by direct code reading: discover.rs already uses rayon::prelude::* and .par_iter() (src/discover.rs:154) for its tree-sitter parse stage, establishing the parallel-compute/serial-commit pattern Phase 1 reuses. Confirmed enrich_crates (src/rustdoc_enricher.rs:127-134) is currently a plain serial for loop. Confirmed src/parser.rs:184''s extract_visibility already extracts a raw visibility_modifier string from the tree-sitter AST on every discover, independent of rustdoc.","experiments":"Two experiments are required before/during Phase 1 implementation and have not yet been run: (1) time two or more concurrent `cargo +nightly rustdoc` invocations against one shared --target-dir on a real multi-crate workspace, to determine whether cargo''s own build-lock serializes them anyway -- this determines whether Phase 1''s parallelization needs per-crate target dirs instead, trading away the compiled-dependency reuse the shared dir was originally chosen for (RFC-0002''s open question 2, still unresolved by this PDR). (2) time enrich_crates end-to-end on a workspace of the size that originally motivated RFC-0002, to get a real before/after wall-clock comparison -- this repo''s own single small crate (1.9s warm-cache rustdoc run, measured during the RFC-0002 spike) is not representative of the felt multi-crate problem this PDR exists to address.","failure_modes":"Preserved from PDR-0001''s documented failure_modes: a single crate''s cargo/parse failure still degrades to a per-crate warn+skip, not a hard stop -- in Phase 1 this becomes a rayon-mapped Result collected and filtered the same way today''s for-loop''s `match ... Err(e) => warn!` already does. rustdoc-types deserialization failure on data the current raw-Value parser would have silently tolerated is a new possible failure point; it should degrade the same way (warn+skip that one crate) unless it is a full format_version mismatch affecting every crate, which remains the existing loud bail!.","interfaces":"No CLI-facing interface changes. `graphlite discover`/`graphlite check` behavior is unchanged from the caller''s perspective except: faster wall-clock time on multi-crate workspaces (Phase 1, pending the target-dir locking experiment), and more consistent visibility values for private/default-visibility items once the Phase 1 overwrite fix lands.","open_questions":"1. Cargo target-dir locking behavior under concurrent rustdoc invocations -- unresolved, needs experiment (see `experiments`) before Phase 1 lands. 2. Whether rustdoc-types'' supported format_version range covers this project''s pinned nightly toolchain''s actual output -- needs verification before adoption. 3. The quiescent-signal reliability gap from RFC-0002-EV-001 -- needs investigation before Phase 2 can be considered at all. 4. Whether to retain rustdoc''s finer-grained restricted::path visibility form as a secondary enrichment once tree-sitter''s raw modifier text becomes the primary source, or drop rustdoc from the visibility signal entirely.","problem":"cli/src/rustdoc_enricher.rs''s enrich_crates runs `cargo +nightly rustdoc --output-format json` once per affected crate, strictly serially (a plain for loop), even though this codebase already depends on rayon and uses it for the tree-sitter parse stage in discover.rs -- felt directly and repeatedly by this project''s own maintainer on multi-crate workspaces. Separately, apply_json parses rustdoc JSON as raw serde_json::Value rather than through a typed schema, so a future nightly rustdoc-json format change surfaces as a silently-None .get()/.as_str() chain rather than a compiler error. A feasibility spike (RFC-0002-EV-001, 2026-08-21) additionally found that the codebase''s existing lsp_client.rs (used today only for interactive `rename`) can plausibly source two of rustdoc''s three signals (qualified_name, trait_impl) with comparable fidelity, but rust-analyzer''s readiness signal (`experimental/serverStatus{quiescent:true}`) did not fire within 170s in that spike, and the third signal (visibility) turns out to already be available for free from tree-sitter''s existing extract_visibility (parser.rs:184), which rustdoc_enricher.rs currently overwrites unconditionally with no NULL-guard.","proposed_design":"Two phases, deliberately not committed to in the same implementation pass, per RFC-0002''s alternatives (a)/(b)/(c) being independently valuable rather than a single bundled change.\n\nPHASE 1 -- parallel rustdoc + typed parsing (ready to implement once the two open experiments below are run):\n1. Hoist build_node_map out of the per-crate loop: build it once from a single `SELECT id, file, range_start FROM nodes` query before enrichment starts, wrapped in an Arc for shared read-only access across worker threads (it is currently rebuilt, wastefully, inside every per-crate apply_json call).\n2. Split run_and_apply/apply_json into a pure Send-safe stage (run_cargo_rustdoc + JSON parse + node_map lookup, producing an in-memory CrateEnrichment{node_updates, impl_trait_edges} value per crate, no DB access) and a DB-application stage. Run the pure stage via `crates.par_iter().map(...).collect::<Vec<_>>()`, mirroring discover.rs''s existing `.par_iter()` tree-sitter parse stage (src/discover.rs:154). A crate whose cargo invocation or JSON parse fails produces an Err, degraded to a warn+skip exactly as today''s for-loop does -- this preserves PDR-0001''s documented failure_modes exactly, just via rayon''s map/collect instead of a for loop''s match arm.\n3. Apply all collected CrateEnrichments to the database serially, in one transaction, on the calling thread -- the same parallel-compute/serial-single-transaction-commit pattern already established elsewhere in this codebase.\n4. Adopt the rustdoc-types crate: replace apply_json''s raw serde_json::Value navigation with typed deserialization into rustdoc_types::Crate. Field access becomes compiler-checked; an upstream schema break becomes a compile error instead of a silently-None access chain. Keep the existing EXPECTED_FORMAT_VERSION runtime assertion as a belt-and-suspenders check -- rustdoc-types targets a version range, not an exact pin, so the runtime assertion still catches drift within that range that the type definitions alone would not.\n5. Fix the visibility overwrite bug found in the spike: stop letting rustdoc_enricher.rs unconditionally clobber a value tree-sitter''s extract_visibility (parser.rs:184) already computed for free on every discover. Decide during implementation whether rustdoc''s finer-grained `restricted::path` form is worth retaining as a secondary enrichment only when tree-sitter''s raw modifier text can''t already express the same distinction (it usually can, since tree-sitter captures the exact `pub(...)` text verbatim from source).\n\nPHASE 2 -- LSP-based qualified_name/trait_impl sourcing, explicitly deferred and not committed to by this PDR:\nNot to be implemented until the RFC-0002-EV-001 quiescent-signal gap is understood -- either the actual readiness condition rust-analyzer needs is found (a different notification, a validated settle-window heuristic, or evidence that per-file documentSymbol/hover requests are safe pre-quiescence for this specific use case), or the gap is shown not to matter at production scale. Visibility sourcing does not carry over to this phase regardless of outcome -- tree-sitter already covers it per Phase 1 step 5. Requires a materially different lsp_client.rs than exists today: the current client is single-in-flight and blocking, built for one interactive rename call; bulk enrichment across many symbols needs request pipelining or must accept O(symbols) sequential round-trips, and either approach needs its own timing validation against rustdoc JSON''s per-crate subprocess cost before it can be justified as an improvement rather than a regression. This phase is the eventual path to collapsing tree-sitter+rustdoc+LSP down to tree-sitter+LSP as graphlite''s two code-understanding mechanisms, but is not this PDR''s committed scope.","requirements":"enrich_crates wall-clock time must improve on multi-crate workspaces, without changing per-crate failure semantics (a single crate''s rustdoc/parse failure must still degrade to a warn+skip, not a hard stop, per PDR-0001''s documented failure_modes). rustdoc JSON parsing must become resilient to schema drift at compile time rather than failing silently at runtime. qualified_name/visibility/trait_impl fidelity must not regress. The visibility overwrite bug found in the spike must be fixed regardless of which enrichment source is used going forward. Any LSP-based sourcing must not be adopted until it is demonstrably as reliable as the current rustdoc-JSON path, not merely as fast in one favorable spike run -- efficiency gains are only acceptable where correctness is verified first, not assumed.","resulting_decisions":"This PDR proposes Phase 1 (parallelize enrich_crates + adopt rustdoc-types + fix the visibility overwrite bug) as the concrete next implementation step, contingent on first resolving the two open experiments listed above -- not yet approved for implementation as of this draft. Phase 2 (LSP-based qualified_name/trait_impl sourcing) is deliberately deferred, not rejected -- to be revisited as its own follow-up record once the quiescent-signal reliability gap is understood, rather than implemented speculatively alongside Phase 1''s lower-risk changes.","risks":"Phase 1''s split of run_and_apply into pure-compute and serial-apply stages is a real refactor, not a trivial wrapper -- risk of subtly changing behavior if any ordering dependency exists between crates in the current per-crate flow (e.g. if a later crate''s rustdoc run were ever found to depend on an earlier crate''s node having just been inserted by build_node_map -- hoisting node_map to a single upfront snapshot would break that; this has not been verified absent in the current code and should be checked before implementation, not assumed). rustdoc-types adoption risk: must verify the crate''s supported format_version range actually covers this project''s EXPECTED_FORMAT_VERSION=57 before starting the migration, not discover a mismatch mid-implementation. Phase 2''s risks are covered under alternatives/constraints and are the reason it is not in this PDR''s committed scope."}', 3, '2026-08-21T16:38:24.792676802+00:00', '2026-08-21T16:43:44.172834037+00:00', 'rust-enrichment-redesign-parallel-rustdoc-typed-parsing-phased-l');
INSERT INTO engineering_record (id, kind, number, title, status, document, revision, created_at, updated_at, slug) VALUES ('RFC-0001', 'RFC', 1, 'Dynamic language discovery via heuristics and parsing', 'draft', '{"alternatives":"Keep the current fixed compile-time language list (what actually shipped): simpler, fully typed, no runtime grammar-loading machinery, but requires a release to add a language and cannot handle a codebase mixing an unsupported language gracefully beyond skip-with-warning.","constraints":"No hard failure on a missing grammar crate for a detected language -- log and skip. Detection must not require the project to build.","motivation":"The current language list (Rust, TypeScript, JavaScript, Svelte, HTML, CSS) is fixed at compile time, one tree-sitter grammar crate per language, hardcoded in language.rs. GRAPHLITE-SPEC.xml (committed alongside the v0.2 LSP-enrichment release) proposed replacing this with runtime grammar discovery: no assumption about which languages are supported ahead of time, detection instead driven by a three-tier heuristic (file extension, then shebang line, then actual parse-attempt validation with grammar-family fallback).","non_goals":"The spec does not propose changing the indexing/query pipeline itself (tree-sitter parse -> symbols/edges -> SQLite -> XML output) -- only how the set of active languages is determined and reported.","outcome":"Not implemented. Verified directly against the current codebase: `graphlite discover --help` / `capabilities --json` show no `--list-grammars`, `--dry-run`, or `--grammar-debug` flags (discover currently takes no flags at all); language.rs implements a fixed extension-to-language match, not runtime grammar scanning; no `languages` table exists in the current schema. `git log --follow` shows this file was added in the same commit as v0.2''s LSP enrichment work and has not been touched since -- consistent with a proposal that was written, not pursued, and not since revisited. Recorded here as draft, not accepted or withdrawn, since no explicit review or withdrawal decision is evidenced; a maintainer should either move this forward or formally withdraw it so the record reflects an actual decision rather than an open, silently-abandoned one.","problem":"A fixed, compile-time language list means adding a language requires a new graphlite release. The proposal''s premise is that a codebase''s actual language mix should be discovered, not pre-declared, and that detection should degrade gracefully (parseable_unknown, unparseable-metadata-only) rather than simply skipping unrecognized extensions.","proposal":"Runtime grammar discovery as described under `scope`, with the CLAUDE_DISCOVERY_PROTOCOL section of the spec explicitly written as agent-facing guidance (\"never assume languages, wait for discover output first\").","questions_for_review":"Was this proposal ever formally reviewed, or written and left in draft? -- Left in draft: this record backfills it honestly rather than assuming acceptance. Does the current fixed-list implementation already satisfy the real need well enough that the added runtime-discovery complexity isn''t worth it? -- Open; no evidence either way was found in this codebase''s history. Is `tier3_parsing_validation`''s try-then-fallback-grammar-family approach (e.g. attempting a rust parse on an unrecognized C-like file) something the tree-sitter query layer can actually support today, or does it require substantial new query-file infrastructure per grammar family?","scope":"As specified in GRAPHLITE-SPEC.xml: extension-to-language mapping with a shebang-line fallback, a parse-attempt validation tier with grammar-family fallback ordering (e.g. typescript tried before javascript for .js files), a new `languages` SQLite table recording per-language file counts/parse success/confidence, and CLI surface additions (`discover --list-grammars`, `--dry-run`, `--grammar-debug`) plus a `symbols --language` filter over the dynamically discovered set."}', 1, '2026-08-21T15:46:21.980919543+00:00', '2026-08-21T15:46:21.980919543+00:00', 'dynamic-language-discovery-via-heuristics-and-parsing');
INSERT INTO engineering_record (id, kind, number, title, status, document, revision, created_at, updated_at, slug) VALUES ('RFC-0002', 'RFC', 2, 'Redesign rustdoc-based Rust enrichment', 'draft', '{"alternatives":"(a) Parallelize enrich_crates as-is (rayon .par_iter() over crates, mirroring discover.rs) -- lowest-risk, addresses the concretely-felt slowness directly, does not touch the JSON-parsing or dual-identity-space concerns. (b) Adopt the rustdoc-types crate for typed parsing -- reduces schema-drift maintenance burden, does not address serial execution or the tree-sitter/rustdoc identity-reconciliation fragility (span_file_match_keys'' four match-form normalization, four dedicated tests). (c) Investigate replacing rustdoc JSON with the existing LSP client (lsp_client.rs) as the single semantic-enrichment source -- would remove one of three code-understanding mechanisms entirely and might sidestep the identity-reconciliation problem if the LSP path can address symbols the same way tree-sitter does. RESOLVED 2026-08-21: the blocking question over whether lsp_client.rs is actively maintained or scheduled for removal is settled -- it is actively maintained. `rename` is a live, working command (main.rs Commands::Rename, dispatched through `graphlite watch`''s IPC to a persistent rust-analyzer client in lsp_client.rs), rebuilt by commit 12695cc (''feat: rename via rust-analyzer LSP through watch daemon IPC'', 2026-04-05) -- eight commits and one week after 61ec423 (2026-03-29) added the README.md line stating rename ''is no longer implemented in CLI.'' That README line is stale documentation debt, not the accurate forward direction; it was never updated after rename was rebuilt on the watch-daemon IPC path. Alternative (c) is therefore not foreclosed and is worth evaluating on its technical merits -- the open question is now purely technical, not organizational: can rustdoc JSON''s three signals (qualified_name, visibility, trait_impl/IMPL_TRAIT edges) be obtained through the same persistent rust-analyzer LSP client rename already uses, without regressing fidelity or reintroducing the identity-reconciliation fragility in a different form. These three alternatives are not mutually exclusive -- (a) and (b) are compatible with either doing or not doing (c).","constraints":"Rustdoc-derived data (qualified_name, visibility, trait_impl/IMPL_TRAIT edges) must remain available at the same fidelity for Rust projects; this is a performance/robustness/architecture redesign, not a feature reduction. Whatever replaces or restructures the current mechanism must still degrade to a per-crate warning-and-skip on failure, matching the existing failure_modes documented in PDR-0001, not a hard stop for the whole index.","motivation":"Rustdoc-based enrichment (qualified names, visibility, trait-impl edges) is the one stage of the indexing pipeline that is felt, directly and repeatedly, as slow -- reported independently by this project''s own maintainer, not just observed as a theoretical concern. It is also the pipeline''s most fragile stage: it depends on the nightly toolchain and an explicitly unstable JSON format, and reconciles its own identity space (rustdoc spans) against tree-sitter''s (parsed node ranges) via best-effort, multi-form file-path string matching.","non_goals":"This RFC does not propose changing the tree-sitter parsing stage, the use-statement resolver, role inference, or any query-command output format. It does not extend language support. It does not itself correct the stale README.md line calling `rename` deprecated (see `alternatives` -- resolved 2026-08-21: the line is factually wrong and should be fixed, but that is a one-line documentation correction independent of this RFC''s scope, not a blocker for it).","outcome":"Draft. Written directly from a real, verified investigation of this codebase in the same session that backfilled PDR-0001 -- not yet reviewed by a maintainer. No implementation has started.","problem":"cli/src/rustdoc_enricher.rs''s enrich_crates runs `cargo +nightly rustdoc --output-format json` once per affected crate, strictly serially (a plain for loop), even though this codebase already depends on rayon and uses it for the tree-sitter parse stage in discover.rs. Each invocation is a real subprocess: toolchain startup, analysis, and JSON serialization, not just a cache hit, even with a shared --target-dir. On a multi-crate workspace this is very likely the dominant cost of a full re-index. Separately, apply_json parses the rustdoc JSON as raw serde_json::Value rather than through the rustdoc-types crate (not a dependency here) -- it does correctly assert format_version against an EXPECTED_FORMAT_VERSION constant and fails loudly on mismatch, which is the right defensive move, but every future nightly rustdoc-json schema change still requires manually re-verifying each ad hoc .get()/.as_str()/.as_object() access chain by hand rather than getting a compiler error from a typed struct.","proposal":"Not yet settled -- this RFC exists to get the three scope questions reviewed before a PDR commits to one answer. The evidence and one plausible reading are laid out under `alternatives`.","questions_for_review":"1. [RESOLVED 2026-08-21] Is lsp_client.rs actively maintained, or is README.md''s deprecation note the accurate forward direction? Actively maintained: rebuilt in 12695cc (2026-04-05) to back the live `rename` command via `graphlite watch`''s IPC, a week after the README.md line (added in 61ec423, 2026-03-29) that calls it deprecated -- that line is stale, not descriptive of current intent. This unblocks alternative (c) for consideration. 2. Is parallelizing enrich_crates (alternative a) safe given the shared --target-dir across crates -- does cargo''s own locking make concurrent `cargo +nightly rustdoc` invocations against one target dir safe, or would parallelizing require per-crate target dirs (losing the current compiled-dependency reuse the shared dir was chosen for)? 3. Would adopting rustdoc-types (alternative b) meaningfully reduce the four-form path-matching fragility, or is that fragility inherent to reconciling any two independently-computed identity spaces regardless of how the JSON is parsed? 4. If alternative (c) is pursued: can the LSP client obtain qualified_name/visibility/trait_impl signals at the same fidelity rustdoc JSON provides today, and would it still support the per-crate warning-and-skip failure mode required by `constraints`?","scope":"cli/src/rustdoc_enricher.rs and its call sites in discover.rs. Three concrete questions to resolve: (1) should enrich_crates parallelize its per-crate cargo invocations the way discover.rs already parallelizes tree-sitter parsing; (2) should apply_json''s raw serde_json::Value parsing be replaced with the rustdoc-types crate for typed, compiler-checked access; (3) should rustdoc JSON remain a separate enrichment mechanism at all, or could the LSP client already present in this codebase (lsp_client.rs, currently used for the `rename` command) absorb what rustdoc JSON currently provides -- collapsing three code-understanding mechanisms (tree-sitter, rustdoc JSON, LSP) to two."}', 2, '2026-08-21T15:46:22.037456627+00:00', '2026-08-21T16:05:11.116307115+00:00', 'redesign-rustdoc-based-rust-enrichment');

INSERT INTO record_relation (source_id, relation, target_id) VALUES ('EDR-0001', 'implements', 'PDR-0002');
INSERT INTO record_relation (source_id, relation, target_id) VALUES ('PDR-0002', 'derived-from', 'RFC-0002');
INSERT INTO record_relation (source_id, relation, target_id) VALUES ('RFC-0001', 'relates-to', 'PDR-0001');
INSERT INTO record_relation (source_id, relation, target_id) VALUES ('RFC-0002', 'relates-to', 'PDR-0001');

INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('EDR-0001', 1, '{"alternatives":"Retain a shared target directory, which Cargo serializes with its build lock; retain serial enrichment; keep raw serde_json navigation; or guard rather than remove rustdoc visibility writes. The experiment showed per-crate target directories are required for actual overlap, and the visibility sample showed rustdoc overwrote private with crate.","consequences":"The representative three-crate workspace improved from 3.01s before to 1.67s after. Compiled dependency artifacts are less reusable across crates because target directories are isolated. Qualified names, signatures, trait implementations, and IMPL_TRAIT edges are computed without database access and committed serially. Format-version mismatches remain loud; other crate failures warn and skip.","context":"Implementing PDR-0002 Phase 1 in src/rustdoc_enricher.rs after the required target-locking, timing, rustdoc-types, and visibility experiments.","decision":"Hoist one SQLite node-map snapshot into Arc, compute typed rustdoc enrichment per crate in rayon workers using per-crate Cargo target directories, then apply all successful results serially in one transaction. Adopt rustdoc-types 0.57.4 for format_version 57 and stop writing visibility from rustdoc so tree-sitter remains authoritative.","evidence":"Shared-target concurrent rustdoc: alpha 0.67s and beta 1.15s, with beta blocking on Cargo build-directory lock. Baseline graphlite discover/enrich on the same workspace: 3.01s. Changed implementation: 1.67s with three concurrent rustdoc jobs. Visibility sample after change: private_item=private, public_item=pub, crate_item=pub(crate), restricted_item=pub(in crate::inner). rustdoc-types 0.57.x declares FORMAT_VERSION 57."}', '2026-08-21T16:59:52.169104700+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('PDR-0001', 1, '{"alternatives":"A single unified language-server-protocol backend (rust-analyzer, tsserver, etc.) instead of tree-sitter+rustdoc: rejected as the primary mechanism because LSP servers require a working build and per-language server management; tree-sitter''s syntax-only parsing tolerates broken/mid-edit code and covers six languages uniformly. An LSP client (lsp_client.rs) exists in this codebase for one specific feature (semantic rename) rather than as the core indexing mechanism -- README.md now states rename is deprecated in favor of editor-native LSP rename, though the CLI (`graphlite rename --help`, main.rs Commands::Rename) still dispatches it; this inconsistency is unresolved as of this record.","components":"tree-sitter parser + per-language .scm query files (queries/*.scm) for symbol/call extraction; rustdoc_enricher.rs (cargo invocation, JSON parsing, node reconciliation); resolver.rs (use-statement resolution to CALLS_RESOLVED edges); roles.rs (topology-based role classification); query.rs (all read-path commands and XML rendering); schema.rs (SQLite schema, incremental hashing); watch.rs (filesystem watch + re-index); annotate.rs (persistent human/LLM notes on symbols, with staleness tracking against re-indexed content); policy.rs + violations.rs (architecture layer/context coupling rules, built-in packs, custom overrides).","constraints":"Must work without requiring the target project''s build to succeed (tree-sitter parses syntax, not semantics, so it tolerates broken code). Semantic enrichment for Rust is necessarily best-effort on top of that, since it depends on a working compiler toolchain. Output must carry its own token cost so an agent can budget context spend without guessing.","data_model":"SQLite tables include nodes (symbol id, stable_id, kind, file, range, visibility, role, fan_in/fan_out), edges (from/to node id, edge_type, source, confidence_tier), annotations (intent, behavior, tags, source, confidence, staleness), node_diagnostics (clippy findings), and crate-risk tables (cargo-audit ingestion). stable_id (e.g. \"src/policy.rs::fn::effective_policy\") is the durable cross-query identifier; numeric node ids are session-local.","evidence":"Verified directly, in a real session working against both this codebase and a second real Rust workspace (github.com Strata project, 4 crates / 211 symbols): `graphlite deps` correctly derived crate dependency direction with zero manual configuration; `graphlite context`/`blast-radius`/`trace-path` reproduced call-structure facts (e.g. cli/src/publish.rs::fn::run -> stage::publish -> stage::replace_target in 2 hops) that would otherwise require reading multiple full files; policy layering (kernel/records=domain, store=infra, strata=adapter) matched the target project''s own documented architecture with zero manual dependency-direction violations found.","experiments":"None formally recorded prior to this backfill. The verification described under `evidence` was exploratory, ad hoc, and not captured as a repeatable experiment at the time it was run.","failure_modes":"Missing grammar or unparseable file: skipped with a logged warning, not a hard failure. Rustdoc enrichment failing for one crate (nightly not installed, cargo error) is caught per-crate in enrich_crates and logged as a warning, not propagated -- the rest of the index still completes. A rustdoc JSON format_version mismatch against EXPECTED_FORMAT_VERSION is a hard, loud failure (bail!) rather than a silent partial parse. Invalid FTS5 query syntax passed to `symbols` currently surfaces as a raw anyhow backtrace rather than a clean error -- an observed gap, not yet fixed.","interfaces":"A single `graphlite` CLI binary (clap-derived subcommands), documented in README.md and in skills/graphlite.md (a Claude Code skill file distributed inside this repo, describing the recommended query-escalation workflow and per-command token budgets). `.graphlite/config.toml` (TOML) configures ignore patterns, workspace crate-to-layer mapping, and policy overrides. No network interface; output is XML (or Markdown via --md) to stdout.","open_questions":"Should rustdoc-based enrichment continue to exist as a separate mechanism from the LSP client already present in this codebase, or should one subsume the other -- and does that decision depend on resolving the rename-deprecation inconsistency noted under `alternatives` first? Tracked forward in RFC-0002.","problem":"An LLM agent working in a codebase needs to answer structural questions (who calls this, what would change if I edit that, what''s the architecture) without either reading whole files defensively (expensive, imprecise, doesn''t scale with codebase size) or lacking any structural ground truth at all (hallucinated call graphs, missed call sites).","proposed_design":"A three-stage pipeline writes into one SQLite database (.graphlite/codegraph.db): (1) tree-sitter parses all supported languages in parallel (rayon) into symbols and syntactic CALLS edges, confidence=0.8; (2) for Rust, `cargo +nightly rustdoc --output-format json` is run per affected crate and the resulting JSON is parsed to attach qualified_name, visibility, and IMPL_TRAIT edges, source=\"rustdoc\"; (3) a use-statement resolver produces CALLS_RESOLVED edges with a high/medium/low confidence tier, source=\"resolver\". A separate role-inference pass classifies each symbol (entrypoint, orchestrator, infra, domain, utility, leaf, model) from graph topology (fan-in/fan-out shape), independent of any per-language logic. Every query command renders XML via a shared writer and reports its own token count in the output header.","requirements":"Index Rust, TypeScript, JavaScript, Svelte, HTML, and CSS source into symbols and call edges. Provide token-metered query commands (map, symbols, graph, context, blast-radius, trace-path) that return XML with an explicit token/line budget the caller controls. Re-indexing must be incremental, keyed on file content hash, so repeated queries against a large codebase stay cheap. For Rust specifically, enrich beyond syntactic tree-sitter facts with real semantic data: qualified names, visibility, trait implementations.","resulting_decisions":"This record captures already-implemented, working design as of the session that backfilled it; it does not itself constitute a new decision. RFC-0002 (rustdoc/cargo enrichment redesign) is the forward-looking record that references this PDR as the description of the system it proposes to change.","risks":"rustdoc enrichment requires the nightly toolchain and consumes unstable, only-loosely-versioned JSON output (mitigated by the format_version assertion, but every nightly rustdoc-json schema change still requires a manual constant bump and re-verification of every raw serde_json::Value access path, since rustdoc-types is not used). rustdoc enrichment runs strictly serially per crate (enrich_crates is a plain for loop) despite rayon already being a dependency used elsewhere in this same pipeline (discover.rs) -- on a multi-crate workspace this is very likely the dominant cost of a full re-index, and is the concrete, felt performance problem motivating RFC-0002. query.rs has grown to 2945 lines mixing orchestration and XML rendering for every command, a maintainability risk independent of correctness."}', '2026-08-21T15:46:21.875777812+00:00', NULL, 'created');
